Here is the Python function `shortest_path(edges, start, end)` using Dijkstra's algorithm. 

It validates the edge weights (raising a `ValueError` for negative weights), handles the edge case where `start` and `end` are the same, and correctly finds the shortest path and its total distance.

```python
import heapq
from collections import defaultdict


def shortest_path(edges, start, end):
    # Check for negative weights
    for u, v, weight in edges:
        if weight < 0:
            raise ValueError("Edge weights cannot be negative.")

    # If start and end are the same
    if start == end:
        return (0, [start])

    # Build the adjacency list
    graph = defaultdict(list)
    for u, v, weight in edges:
        graph[u].append((v, weight))
        # Ensure nodes with no outgoing edges are still in the graph keys
        if v not in graph:
            graph[v] = []

    # If start or end nodes are not in the graph at all
    if start not in graph:
        return (None, None)

    # Priority queue stores tuples of (current_distance, current_node, path)
    pq = [(0, start, [start])]
    visited = set()

    while pq:
        current_distance, current_node, path = heapq.heappop(pq)

        if current_node == end:
            return (current_distance, path)

        if current_node in visited:
            continue
        visited.add(current_node)

        for neighbor, weight in graph[current_node]:
            if neighbor not in visited:
                heapq.heappush(
                    pq,
                    (
                        current_distance + weight,
                        neighbor,
                        path + [neighbor],
                    ),
                )

    # If the priority queue empties and we haven't reached the end
    return (None, None)
```

### Example Usage:

```python
edges = [("A", "B", 1), ("B", "C", 2), ("A", "C", 5)]

# Example 1: Standard shortest path
print(shortest_path(edges, "A", "C"))
# Output: (3, ['A', 'B', 'C'])

# Example 2: Start and end are the same
print(shortest_path(edges, "A", "A"))
# Output: (0, ['A'])

# Example 3: Route does not exist
print(shortest_path(edges, "C", "A"))
# Output: (None, None)

# Example 4: Negative weight raises ValueError
try:
    shortest_path([("A", "B", -1)], "A", "B")
except ValueError as e:
    print(e)
# Output: Edge weights cannot be negative.
```

